import{_ as a,c as t,o as i,aj as r}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse('{"title":"Pita Bread","description":"Soft pocket pita with balanced chew and reliable puff, using a partial whole wheat blend for more flavor without giving up structure.","frontmatter":{"title":"Pita Bread","description":"Soft pocket pita with balanced chew and reliable puff, using a partial whole wheat blend for more flavor without giving up structure.","head":[["meta",{"name":"description","content":"Soft pocket pita with balanced chew and reliable puff, using a partial whole wheat blend for more flavor without giving up structure."}],["meta",{"property":"og:title","content":"Pita Bread"}],["meta",{"property":"og:description","content":"Soft pocket pita with balanced chew and reliable puff, using a partial whole wheat blend for more flavor without giving up structure."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/pita.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Pita Bread"}],["meta",{"name":"twitter:description","content":"Soft pocket pita with balanced chew and reliable puff, using a partial whole wheat blend for more flavor without giving up structure."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/pita.html"}]]},"headers":[],"relativePath":"recipes/pita.md","filePath":"recipes/pita.md"}'),l={name:"recipes/pita.md"};function o(n,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="pita-bread" tabindex="-1">Pita Bread <a class="header-anchor" href="#pita-bread" aria-label="Permalink to “Pita Bread”">​</a></h1><p>This pita formula is built for a strong puff, tender interior, and a pocket that actually opens. It follows the same overall direction as the ChainBaker-style dough, but uses <strong>25% whole wheat</strong> instead of half for a slightly lighter result. Use the <a href="https://kitchenratio.com/calculator/flatbread/pita/" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch.</p><div class="recipe-glance"><div class="recipe-glance-card"><strong>Style</strong><span>Soft pocket pita with a mild whole-wheat blend and balanced chew.</span></div><div class="recipe-glance-card"><strong>Yield</strong><span>About 8 pitas at roughly 104g each before baking.</span></div><div class="recipe-glance-card"><strong>Best For</strong><span>Hot steels or stones, wraps, sandwiches, and reliable pocket formation.</span></div></div><h2 id="baker-s" tabindex="-1">Baker&#39;s % <a class="header-anchor" href="#baker-s" aria-label="Permalink to “Baker&#39;s %”">​</a></h2><ul><li><strong>Bread flour</strong> - 75%</li><li><strong>Whole wheat flour</strong> - 25%</li><li><strong>Water</strong> - 64%</li><li><strong>Salt</strong> - 2%</li><li><strong>Olive oil</strong> - 2%</li><li><strong>Instant dry yeast</strong> - 1%</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Bread flour</strong> - 375g (75%)</li><li><strong>Whole wheat flour</strong> - 125g (25%)</li><li><strong>Water</strong> - 320g (64%)</li><li><strong>Salt</strong> - 10g (2%)</li><li><strong>Olive oil</strong> - 10g (2%)</li><li><strong>Instant dry yeast</strong> - 5g (1%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch usually makes <strong>8 pitas</strong> at about <strong>104g dough each</strong> before baking.</p></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine flour, yeast, and most of the water.</li><li>Mix until no dry flour remains, then rest 10 minutes.</li><li>Add salt, olive oil, and remaining water.</li><li>Knead until smooth and moderately developed, about <strong>6-8 minutes</strong>.</li></ul><h3 id="_2-bulk-fermentation" tabindex="-1">2. Bulk Fermentation <a class="header-anchor" href="#_2-bulk-fermentation" aria-label="Permalink to “2. Bulk Fermentation”">​</a></h3><ul><li>Cover and ferment at room temperature until expanded by about 75%, usually <strong>60-90 minutes</strong>.</li></ul><h3 id="_3-divide-and-pre-shape" tabindex="-1">3. Divide And Pre-Shape <a class="header-anchor" href="#_3-divide-and-pre-shape" aria-label="Permalink to “3. Divide And Pre-Shape”">​</a></h3><ul><li>Divide into <strong>8 equal pieces</strong>.</li><li>Shape into tight balls.</li><li>Cover and rest <strong>20 minutes</strong> so the dough relaxes before rolling.</li></ul><h3 id="_4-roll" tabindex="-1">4. Roll <a class="header-anchor" href="#_4-roll" aria-label="Permalink to “4. Roll”">​</a></h3><ul><li>Lightly flour the bench.</li><li>Roll each ball into a round about <strong>6-7 inches</strong> wide and roughly <strong>1/4 inch</strong> thick.</li><li>Keep rounds covered while you work so the surface does not dry out.</li></ul><h3 id="_5-final-rest" tabindex="-1">5. Final Rest <a class="header-anchor" href="#_5-final-rest" aria-label="Permalink to “5. Final Rest”">​</a></h3><ul><li>Let the rolled rounds rest <strong>10-15 minutes</strong> before baking.</li><li>This helps the dough relax and improves pocket formation.</li></ul><h3 id="_6-bake" tabindex="-1">6. Bake <a class="header-anchor" href="#_6-bake" aria-label="Permalink to “6. Bake”">​</a></h3><ul><li>Preheat a baking steel, stone, or inverted sheet pan for <strong>45 minutes</strong> at <strong>500-550F</strong>.</li><li>Bake pitas one or two at a time until fully puffed and lightly colored, usually <strong>2-3 minutes</strong>.</li><li>Do not overbake or they will dry out.</li></ul><h3 id="_7-steam-and-hold" tabindex="-1">7. Steam And Hold <a class="header-anchor" href="#_7-steam-and-hold" aria-label="Permalink to “7. Steam And Hold”">​</a></h3><ul><li>Transfer baked pitas to a towel-lined bowl or covered container.</li><li>Keep them covered as they cool so they stay soft and flexible.</li></ul><h2 id="what-to-adjust-first" tabindex="-1">What to Adjust First <a class="header-anchor" href="#what-to-adjust-first" aria-label="Permalink to “What to Adjust First”">​</a></h2><ul><li><strong>No pocket</strong>: hotter baking surface, slightly thicker roll, or a little more final rest.</li><li><strong>Too stiff</strong>: give the dough a longer rest before rolling or raise hydration 1-2%.</li><li><strong>Too sticky to handle</strong>: flour the bench lightly or back hydration down toward 62%.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/yield-planner.html">Yield Planner</a></li><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',32)])])}const p=a(l,[["render",o]]);export{g as __pageData,p as default};
